#!/usr/bin/env node
/* eslint-disable no-console */
/**
 * Merge PHP Coverage Files
 *
 * This script merges individual PHP coverage JSON files (generated by
 * php-coverage-collector.php) into a single coverage report.
 *
 * Output formats:
 * - JSON (for further processing)
 * - HTML (human-readable report)
 * - LCOV (for CI integration)
 *
 * Usage:
 *   node scripts/merge-php-coverage.js [--format=json|html|lcov|all] [--output=dir]
 */

const fs = require( 'fs' );
const path = require( 'path' );

const COVERAGE_DIR = path.join( process.cwd(), '.php-coverage' );
const OUTPUT_DIR = path.join( process.cwd(), 'coverage', 'php-e2e' );
const SOURCE_DIR = path.join( process.cwd(), 'includes' );

// Docker container path prefix to strip for relative paths.
const CONTAINER_PLUGIN_PATH =
	'/var/www/html/wp-content/plugins/secure-custom-fields';

/**
 * Parse command line arguments.
 *
 * @return {Object} Parsed arguments.
 */
function parseArgs() {
	const args = {
		format: 'all',
		output: OUTPUT_DIR,
	};

	process.argv.slice( 2 ).forEach( ( arg ) => {
		if ( arg.startsWith( '--format=' ) ) {
			args.format = arg.split( '=' )[ 1 ];
		} else if ( arg.startsWith( '--output=' ) ) {
			args.output = arg.split( '=' )[ 1 ];
		}
	} );

	return args;
}

/**
 * Recursively find all PHP files in a directory.
 *
 * @param {string} dir - Directory to scan.
 * @param {Array}  files - Accumulator for found files.
 * @return {Array} Array of absolute file paths.
 */
function findPhpFiles( dir, files = [] ) {
	const entries = fs.readdirSync( dir, { withFileTypes: true } );

	for ( const entry of entries ) {
		const fullPath = path.join( dir, entry.name );

		if ( entry.isDirectory() ) {
			// Skip vendor, node_modules, tests directories.
			if (
				! [ 'vendor', 'node_modules', 'tests' ].includes( entry.name )
			) {
				findPhpFiles( fullPath, files );
			}
		} else if ( entry.isFile() && entry.name.endsWith( '.php' ) ) {
			files.push( fullPath );
		}
	}

	return files;
}

/**
 * Parse a PHP file to find executable line numbers.
 * Returns line numbers that contain executable code (not comments, not blank, not just braces).
 *
 * @param {string} filePath - Path to PHP file.
 * @return {Array} Array of executable line numbers.
 */
function findExecutableLines( filePath ) {
	const content = fs.readFileSync( filePath, 'utf8' );
	const lines = content.split( '\n' );
	const executableLines = [];

	let inMultiLineComment = false;
	let inHeredoc = false;
	let heredocEnd = null;

	for ( let i = 0; i < lines.length; i++ ) {
		const lineNum = i + 1;
		let line = lines[ i ].trim();

		// Handle heredoc/nowdoc.
		if ( inHeredoc ) {
			if ( line === heredocEnd || line === heredocEnd + ';' ) {
				inHeredoc = false;
				heredocEnd = null;
			}
			continue;
		}

		// Check for heredoc/nowdoc start.
		const heredocMatch = line.match( /<<<['"]?(\w+)['"]?$/ );
		if ( heredocMatch ) {
			inHeredoc = true;
			heredocEnd = heredocMatch[ 1 ];
			executableLines.push( lineNum );
			continue;
		}

		// Handle multi-line comments.
		if ( inMultiLineComment ) {
			if ( line.includes( '*/' ) ) {
				inMultiLineComment = false;
				// Check if there's code after the comment end.
				const afterComment = line.split( '*/' )[ 1 ].trim();
				if ( afterComment && ! afterComment.startsWith( '//' ) ) {
					executableLines.push( lineNum );
				}
			}
			continue;
		}

		// Check for multi-line comment start.
		if ( line.startsWith( '/*' ) || line.startsWith( '/**' ) ) {
			if ( ! line.includes( '*/' ) ) {
				inMultiLineComment = true;
			}
			continue;
		}

		// Skip empty lines.
		if ( line === '' ) {
			continue;
		}

		// Skip single-line comments.
		if ( line.startsWith( '//' ) || line.startsWith( '#' ) ) {
			continue;
		}

		// Skip PHP open/close tags alone.
		if ( line === '<?php' || line === '?>' || line === '<?php' ) {
			continue;
		}

		// Skip lines that are just braces or structural.
		if ( /^[{})\]]+;?$/.test( line ) ) {
			continue;
		}

		// Skip lines that are just class/function declarations without code.
		// These are structural but we include them as they're part of the definition.
		if (
			/^(abstract\s+)?(class|interface|trait|enum)\s+\w+/.test( line ) ||
			/^(public|private|protected|static|\s)*function\s+\w+/.test( line )
		) {
			executableLines.push( lineNum );
			continue;
		}

		// Skip 'use' statements for traits (they're declarations).
		if ( /^use\s+[\w\\]+\s*;/.test( line ) && ! line.includes( '(' ) ) {
			continue;
		}

		// This line likely contains executable code.
		executableLines.push( lineNum );
	}

	return executableLines;
}

/**
 * Build baseline coverage from all PHP source files.
 * Files not covered by PCOV will have all executable lines marked as uncovered.
 *
 * @return {Object} Baseline coverage data with all files and their executable lines.
 */
function buildBaselineCoverage() {
	console.log( `Scanning PHP files in ${ SOURCE_DIR }...` );
	const phpFiles = findPhpFiles( SOURCE_DIR );
	console.log( `Found ${ phpFiles.length } PHP files.` );

	const baseline = {};

	for ( const file of phpFiles ) {
		const executableLines = findExecutableLines( file );
		if ( executableLines.length > 0 ) {
			// Convert to container path format for consistency with PCOV output.
			const relativePath = file.slice( process.cwd().length );
			const containerPath = CONTAINER_PLUGIN_PATH + relativePath;

			// Mark all executable lines as uncovered (-1 means executable but not hit).
			baseline[ containerPath ] = {};
			for ( const lineNum of executableLines ) {
				baseline[ containerPath ][ lineNum ] = -1;
			}
		}
	}

	return baseline;
}

/**
 * Read all coverage JSON files from the coverage directory.
 *
 * @return {Array|null} Array of coverage data objects, or null if none found.
 */
function readCoverageFiles() {
	if ( ! fs.existsSync( COVERAGE_DIR ) ) {
		console.log( `No PHP coverage directory found: ${ COVERAGE_DIR }` );
		console.log( 'Skipping PHP coverage report generation.' );
		return null;
	}

	const files = fs
		.readdirSync( COVERAGE_DIR )
		.filter( ( f ) => f.endsWith( '.json' ) );

	if ( files.length === 0 ) {
		console.log( 'No PHP coverage files found.' );
		console.log( 'Skipping PHP coverage report generation.' );
		return null;
	}

	console.log( `Found ${ files.length } coverage files.` );

	return files.map( ( file ) => {
		const content = fs.readFileSync(
			path.join( COVERAGE_DIR, file ),
			'utf8'
		);
		return JSON.parse( content );
	} );
}

/**
 * Merge multiple coverage data objects into one.
 *
 * @param {Array} coverageFiles - Array of coverage data objects.
 * @return {Object} Merged coverage data.
 */
function mergeCoverage( coverageFiles ) {
	const merged = {};

	coverageFiles.forEach( ( coverage ) => {
		const data = coverage.data || {};

		Object.entries( data ).forEach( ( [ file, lines ] ) => {
			if ( ! merged[ file ] ) {
				merged[ file ] = {};
			}

			Object.entries( lines ).forEach( ( [ lineNum, hitCount ] ) => {
				// Xdebug returns -1 for "dead code" (unreachable), -2 for "not executed".
				// Positive numbers indicate execution count.
				if ( hitCount > 0 ) {
					merged[ file ][ lineNum ] =
						( merged[ file ][ lineNum ] || 0 ) + hitCount;
				} else if ( ! merged[ file ][ lineNum ] ) {
					// Only set negative values if we haven't seen a positive hit.
					merged[ file ][ lineNum ] = hitCount;
				}
			} );
		} );
	} );

	return merged;
}

/**
 * Calculate coverage statistics.
 *
 * @param {Object} mergedCoverage - Merged coverage data.
 * @return {Object} Coverage statistics.
 */
function calculateStats( mergedCoverage ) {
	let totalLines = 0;
	let coveredLines = 0;
	const fileStats = {};

	Object.entries( mergedCoverage ).forEach( ( [ file, lines ] ) => {
		const lineNumbers = Object.keys( lines );
		const covered = lineNumbers.filter( ( ln ) => lines[ ln ] > 0 ).length;
		const total = lineNumbers.length;

		fileStats[ file ] = {
			total,
			covered,
			percentage:
				total > 0 ? ( ( covered / total ) * 100 ).toFixed( 2 ) : 0,
		};

		totalLines += total;
		coveredLines += covered;
	} );

	return {
		totalFiles: Object.keys( mergedCoverage ).length,
		totalLines,
		coveredLines,
		percentage:
			totalLines > 0
				? ( ( coveredLines / totalLines ) * 100 ).toFixed( 2 )
				: 0,
		files: fileStats,
	};
}

/**
 * Convert container path to relative path for LCOV output.
 *
 * @param {string} containerPath - Full path from Docker container.
 * @return {string} Relative path from project root.
 */
function toRelativePath( containerPath ) {
	if ( containerPath.startsWith( CONTAINER_PLUGIN_PATH ) ) {
		// Remove container prefix, return path relative to project root (with leading dot).
		return '.' + containerPath.slice( CONTAINER_PLUGIN_PATH.length );
	}
	return containerPath;
}

/**
 * Generate LCOV format output.
 *
 * @param {Object} mergedCoverage - Merged coverage data.
 * @return {string} LCOV formatted string.
 */
function generateLcov( mergedCoverage ) {
	let lcov = '';

	Object.entries( mergedCoverage ).forEach( ( [ file, lines ] ) => {
		const relativePath = toRelativePath( file );
		lcov += `SF:${ relativePath }\n`;

		Object.entries( lines ).forEach( ( [ lineNum, hitCount ] ) => {
			// PCOV returns: positive = executed count, -1 = executable but not executed.
			if ( hitCount > 0 ) {
				lcov += `DA:${ lineNum },${ hitCount }\n`;
			} else if ( hitCount === -1 ) {
				// Executable but not executed - report as uncovered (0 hits).
				lcov += `DA:${ lineNum },0\n`;
			}
			// hitCount === 0 shouldn't occur with PCOV, but include it if it does.
			else if ( hitCount === 0 ) {
				lcov += `DA:${ lineNum },0\n`;
			}
		} );

		const lineNumbers = Object.keys( lines );
		// Count all executable lines (executed or not executed).
		const linesFound = lineNumbers.filter(
			( ln ) => lines[ ln ] > 0 || lines[ ln ] === -1 || lines[ ln ] === 0
		).length;
		const linesHit = lineNumbers.filter( ( ln ) => lines[ ln ] > 0 ).length;

		lcov += `LF:${ linesFound }\n`;
		lcov += `LH:${ linesHit }\n`;
		lcov += 'end_of_record\n';
	} );

	return lcov;
}

/**
 * Get coverage level class name based on percentage.
 *
 * @param {number} percentage - Coverage percentage.
 * @return {string} Level class name ('low', 'medium', or 'high').
 */
function getLevel( percentage ) {
	if ( percentage < 50 ) {
		return 'low';
	}
	if ( percentage < 80 ) {
		return 'medium';
	}
	return 'high';
}

/**
 * Generate simple HTML report.
 *
 * @param {Object} stats - Coverage statistics.
 * @return {string} HTML report.
 */
function generateHtml( stats ) {
	const sortedFiles = Object.entries( stats.files ).sort(
		( a, b ) => a[ 1 ].percentage - b[ 1 ].percentage
	);

	let html = `<!DOCTYPE html>
<html>
<head>
	<title>PHP E2E Coverage Report</title>
	<style>
		body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; margin: 20px; }
		h1 { color: #333; }
		.summary { background: #f5f5f5; padding: 20px; border-radius: 8px; margin-bottom: 20px; }
		.summary h2 { margin-top: 0; }
		.percentage { font-size: 48px; font-weight: bold; }
		.percentage.low { color: #d32f2f; }
		.percentage.medium { color: #f57c00; }
		.percentage.high { color: #388e3c; }
		table { width: 100%; border-collapse: collapse; }
		th, td { padding: 10px; text-align: left; border-bottom: 1px solid #ddd; }
		th { background: #f5f5f5; }
		.bar { height: 10px; background: #e0e0e0; border-radius: 5px; overflow: hidden; }
		.bar-fill { height: 100%; }
		.bar-fill.low { background: #d32f2f; }
		.bar-fill.medium { background: #f57c00; }
		.bar-fill.high { background: #388e3c; }
	</style>
</head>
<body>
	<h1>PHP E2E Coverage Report</h1>
	<div class="summary">
		<h2>Summary</h2>
		<div class="percentage ${ getLevel( stats.percentage ) }">
			${ stats.percentage }%
		</div>
		<p>${ stats.coveredLines } / ${ stats.totalLines } lines covered across ${
			stats.totalFiles
		} files</p>
	</div>
	<table>
		<thead>
			<tr>
				<th>File</th>
				<th>Coverage</th>
				<th>Lines</th>
			</tr>
		</thead>
		<tbody>`;

	sortedFiles.forEach( ( [ file, fileStats ] ) => {
		const relPath = toRelativePath( file );
		const pct = parseFloat( fileStats.percentage );
		const level = getLevel( pct );

		html += `
			<tr>
				<td>${ relPath }</td>
				<td>
					<div class="bar">
						<div class="bar-fill ${ level }" style="width: ${ pct }%"></div>
					</div>
					${ fileStats.percentage }%
				</td>
				<td>${ fileStats.covered } / ${ fileStats.total }</td>
			</tr>`;
	} );

	html += `
		</tbody>
	</table>
	<p><em>Generated at ${ new Date().toISOString() }</em></p>
</body>
</html>`;

	return html;
}

/**
 * Main function.
 */
function main() {
	const args = parseArgs();

	console.log( 'Building PHP coverage report...' );

	// Step 1: Build baseline from all PHP source files.
	const baseline = buildBaselineCoverage();
	const baselineFileCount = Object.keys( baseline ).length;

	if ( baselineFileCount === 0 ) {
		console.log( 'No PHP source files found in includes/.' );
		return;
	}

	// Step 2: Read PCOV coverage files (if any).
	const coverageFiles = readCoverageFiles();

	// Step 3: Merge PCOV data on top of baseline.
	// Start with baseline (all files, all lines marked as uncovered).
	let merged = { ...baseline };

	if ( coverageFiles !== null ) {
		// Merge PCOV data - this will override baseline values with actual coverage.
		const pcovMerged = mergeCoverage( coverageFiles );

		// Merge PCOV data into baseline.
		for ( const [ file, lines ] of Object.entries( pcovMerged ) ) {
			if ( ! merged[ file ] ) {
				// File from PCOV not in baseline (shouldn't happen, but handle it).
				merged[ file ] = {};
			}

			for ( const [ lineNum, hitCount ] of Object.entries( lines ) ) {
				// PCOV data takes precedence over baseline.
				if ( hitCount > 0 ) {
					merged[ file ][ lineNum ] = hitCount;
				} else if (
					! merged[ file ][ lineNum ] ||
					merged[ file ][ lineNum ] < 0
				) {
					// Only set negative values if we don't have a positive hit.
					merged[ file ][ lineNum ] = hitCount;
				}
			}
		}

		console.log(
			`Merged PCOV data from ${ coverageFiles.length } coverage files.`
		);
	} else {
		console.log( 'No PCOV coverage files found - using baseline only.' );
	}

	const stats = calculateStats( merged );
	const pcovFileCount = coverageFiles ? coverageFiles.length : 0;

	console.log( `\nBaseline: ${ baselineFileCount } PHP files scanned.` );
	console.log( `PCOV: ${ pcovFileCount } coverage files merged.` );

	console.log( `\nCoverage Summary:` );
	console.log( `  Files: ${ stats.totalFiles }` );
	console.log(
		`  Lines: ${ stats.coveredLines } / ${ stats.totalLines } (${ stats.percentage }%)`
	);

	// Create output directory.
	fs.mkdirSync( args.output, { recursive: true } );

	// Generate requested formats.
	const formats =
		args.format === 'all' ? [ 'json', 'lcov', 'html' ] : [ args.format ];

	formats.forEach( ( format ) => {
		let content;
		let filename;

		switch ( format ) {
			case 'json':
				content = JSON.stringify(
					{ stats, coverage: merged },
					null,
					2
				);
				filename = 'coverage.json';
				break;
			case 'lcov':
				content = generateLcov( merged );
				filename = 'lcov.info';
				break;
			case 'html':
				content = generateHtml( stats );
				filename = 'index.html';
				break;
			default:
				console.error( `Unknown format: ${ format }` );
				return;
		}

		const outputPath = path.join( args.output, filename );
		fs.writeFileSync( outputPath, content );
		console.log( `  Written: ${ outputPath }` );
	} );

	console.log( '\nDone!' );
}

main();
